<section id="stockBranches" class="stock-branches" hidden>
 <details id="branchDetails" hidden><summary><?= stock_icon('branch') ?><span>Sucursales</span><?= stock_icon('chevron') ?></summary>
  <div class="branch-toolbar"><label class="branch-search"><?= stock_icon('search') ?><input id="branchSearch" type="search" placeholder="Buscar sucursal o dirección" aria-label="Buscar sucursal"></label><button id="newBranch" class="library-primary stock-icon" type="button" aria-label="Agregar sucursal" title="Agregar sucursal"><?= stock_icon('plus') ?></button></div>
  <div id="branchList" class="branch-list"></div>
 </details>
 <div class="branch-toolbar branch-stock-filter"><label><?= stock_icon('branch') ?><select id="branchFilter" aria-label="Filtrar mis palets por sucursal"><option value="all">Todas las sucursales</option><option value="none">Sin sucursal</option></select></label><button id="shareStockSelection" class="library-secondary" type="button"><?= stock_icon('share') ?> Compartir selección</button></div>
 <p id="branchFilterEmpty" class="stock-muted" hidden>No hay palets en esta sucursal.</p>
 <p id="branchStatus" class="library-status" role="status"></p>
 <details id="stockShareDetails" hidden><summary><?= stock_icon('share') ?><span>Enlaces compartidos</span><?= stock_icon('chevron') ?></summary><div id="stockShareList" class="branch-list"></div></details>
</section>
<dialog id="branchDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('branch') ?> <span id="branchDialogTitle">Nueva sucursal</span></h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div>
 <form id="branchForm"><label>Nombre de la sucursal<input name="name" maxlength="100" placeholder="Ej.: Carrefour Centro" required></label><label>Dirección<input name="address" maxlength="160" placeholder="Ej.: Av. Colón 1234" required></label><div class="branch-form-row"><label>Localidad<input name="locality" maxlength="100" placeholder="Ej.: Córdoba" required></label><label>Provincia<input name="province" maxlength="80" placeholder="Ej.: Córdoba" required></label></div><label><span>Descripción <small>(opcional)</small></span><textarea name="description" rows="2" maxlength="300" placeholder="Ej.: Depósito, entrada por calle lateral"></textarea></label><input type="hidden" name="latitude"><input type="hidden" name="longitude"><details id="branchPointDetails" class="branch-point-details"><summary>Ubicación en el mapa<span class="branch-create-chevron"><?= stock_icon('chevron') ?></span></summary><div id="branchPointMap" class="branch-map" aria-label="Marcar ubicación del local"></div><div class="branch-map-toolbar"><button id="locateBranchPoint" class="library-secondary" type="button"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg> Mi ubicación</button><button id="clearBranchPoint" class="library-secondary" type="button">Quitar ubicación</button></div><p id="branchPointStatus" class="stock-muted" role="status"></p></details><small id="branchAddressSource" class="branch-address-source" hidden>Dirección sugerida con datos de <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>.</small><p id="branchFormStatus" class="library-status" role="status"></p><button class="library-primary" type="submit"><?= stock_icon('check') ?> Guardar sucursal</button></form>
</dialog>
<dialog id="palletBranchDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('branch') ?> <span id="palletBranchTitle">Sucursal del palet</span></h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><div id="palletBranchPreview" class="branch-selected-preview" hidden><div id="palletBranchPreviewInfo"></div><button id="editBranchData" class="library-secondary stock-icon" type="button" aria-label="Editar datos del local" title="Editar datos del local" hidden><?= stock_icon('settings') ?></button><button id="editSelectedBranch" class="library-secondary stock-icon" type="button" aria-label="Cambiar sucursal" title="Cambiar sucursal"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/></svg></button></div><div id="branchPicker" hidden><div class="stock-tabs branch-picker-tabs" role="tablist" aria-label="Elegir sucursal"><button id="branchSearchTab" type="button" role="tab" aria-selected="true" aria-controls="branchSearchPanel"><?= stock_icon('search') ?> Buscar</button><button id="branchLocationTab" type="button" role="tab" aria-selected="false" aria-controls="branchLocationPanel" tabindex="-1"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg> Por ubicación</button></div><div id="branchSearchPanel" role="tabpanel" aria-labelledby="branchSearchTab"><form id="palletBranchForm"><label><span>Sucursal <small>(opcional)</small></span><input id="palletBranchSearch" type="search" autocomplete="off" placeholder="Buscar por nombre o dirección" aria-controls="palletBranchResults"><select id="palletBranchSelect" hidden><option value="">Sin sucursal</option></select></label><div id="palletBranchResults" class="branch-search-results" aria-label="Sucursales disponibles"></div><p id="palletBranchEmpty" class="stock-muted" role="status" hidden>No encontramos una sucursal con esos datos.</p><button id="newPalletBranch" class="library-secondary" type="button" aria-expanded="false" aria-controls="palletBranchCreateSlot">Agregar sucursal<span class="branch-create-chevron"><?= stock_icon('chevron') ?></span></button><p id="palletBranchStatus" class="library-status" role="status"></p><button id="savePalletBranch" class="library-primary" type="submit"><?= stock_icon('check') ?> <span>Guardar</span></button></form><div id="palletBranchCreateSlot" hidden></div></div><div id="branchLocationPanel" role="tabpanel" aria-labelledby="branchLocationTab" hidden><div id="branchLocationMap" class="branch-map" aria-label="Mapa de sucursales"></div><div class="branch-map-toolbar"><button id="locateBranchUser" class="library-secondary" type="button"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v4m0 12v4M2 12h4m12 0h4"/></svg> Mi ubicación</button><span id="branchLocationStatus" class="stock-muted" role="status"></span></div><div id="branchMapChoice" class="branch-map-choice" hidden><p id="branchMapChoiceLabel"></p><div id="branchMapNearby"></div><button id="addBranchAtPoint" class="library-secondary" type="button"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg> Agregar sucursal aquí</button></div></div></div></dialog>
<dialog id="stockShareDialog" class="library-dialog branch-dialog"><div class="library-heading"><h2><?= stock_icon('share') ?> Compartir palets</h2><button class="app-close" data-branch-close type="button" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><form id="stockShareForm"><label>Nombre del enlace<input name="title" maxlength="100" placeholder="Ej.: Mercadería para revisar"></label><div id="stockShareChoices" class="branch-share-choices"></div><p id="stockShareStatus" class="library-status" role="status"></p><button class="library-primary" type="submit"><?= stock_icon('share') ?> Crear enlace</button></form><div id="stockShareResult" hidden><p class="library-status" role="status">Enlace listo. Quien lo reciba podrá consultar el contenido sin registrarse.</p><input id="stockShareURL" readonly aria-label="Enlace público"><div class="branch-toolbar"><button id="copyStockShare" class="library-primary" type="button"><?= stock_icon('share') ?> Compartir enlace</button><a id="openStockShare" class="library-secondary" target="_blank" rel="noopener">Ver enlace</a></div></div></dialog>
